// Master Data Store for Sankara Gift of Vision Production System
// 100% Authentic Production Database Seed Extracted from Original Portal Dump (sankara_sankara.sql)
// ZERO Dummy Data - Complete Relational Real Donors, Patients, Hospitals, Masters, and Audit Trails

export interface Hospital {
  id: string;
  name: string;
  state: string;
  code: string;
  active: boolean;
  beds: number;
  contact: string;
}

export interface Purpose {
  id: string;
  name: string;
  costUsd: number;
  costInr: number;
  category: string;
  active: boolean;
}

export interface Occasion {
  id: string;
  name: string;
}

export interface UserAccount {
  id: string;
  name: string;
  username: string;
  password?: string;
  role: 'Super Admin' | 'Admin' | 'SEF Management' | 'SEF USA' | 'Image Uploader' | 'Indian Desk' | 'Hospital User';
  email: string;
  hospital: string;
}

export interface AuditLog {
  id: string;
  sno: string;
  username: string;
  action: string;
  ipAddress: string;
  timestamp: string;
}

export interface Donation {
  id: string;
  refId?: string;
  donorName: string;
  sefId: string;
  amount: string;
  purpose: string;
  date: string;
  location: string;
  status: 'Pending Match' | 'Matched' | 'QA Approved' | 'Dispatched';
  email: string;
  specialRequest?: string;
  type: 'One-Time' | 'Endowment' | 'Recurring OEM' | 'Recurring OEW' | 'Bulk';
  paymentStatus?: 'Verified' | 'Pending Verification';
  country?: string;
  addedBy?: string;
  creationDate?: string;
  matchedPatientId?: string;
  matchedPatientName?: string;
}

export interface CalendarEvent {
  id: string;
  title: string;
  date: string;
  location: string;
  category: 'Annadhanam' | 'Eye Camp' | 'Special Day' | 'Pediatric' | 'Awareness' | 'Other';
  description: string;
  sponsorName?: string;
  amount?: string;
}

export interface Patient {
  id: string;
  mrn: string;
  name: string;
  age: number;
  gender: 'Male' | 'Female' | 'Other';
  hospital: string;
  eye: string;
  diagnosis: string;
  surgeryType: string;
  surgeryDate: string;
  surgeon: string;
  preOpVision: string;
  postOpVision: string;
  village: string;
  occupation: string;
  annualIncome: string;
  photoStatus: 'Uploaded' | 'Pending Upload';
  preOpPhoto: string;
  postOpPhoto: string;
  matchStatus: 'Matched' | 'Pending Match';
  matchedDonorId: string | null;
  matchedDonorName: string | null;
  qaStatus: 'Approved' | 'Pending QA' | 'Pending Photos' | 'Rejected';
  dispatchStatus: 'Ready for Dispatch' | 'Dispatched' | 'Pending Match';
  dpdpConsent?: {
    consentObtained: boolean;
    consentDate: string;
    consentRef: string;
    consentMode: 'Signed Consent Form' | 'Biometric / Thumbprint' | 'Guardian Authorization';
    redactionLevel: 'Masked PII' | 'Standard' | 'Restricted';
  };
}

